  for(String name:new String[]{"old.manifest","new.manifest"}){Path tamper=Files.createTempDirectory("coord-tamper-").toRealPath();DataCoordinator tc=coordinator(tamper);Path tr=tc.prepare(src(a),null);try{tc.prepare(src(b),s->{if(s.equals("after-marker-invalidate"))throw new IOException("interrupted");});throw new Exception("stage not hit");}catch(IOException expected){}String[] j=new String(Files.readAllBytes(tamper.resolve("state/pending")),"US-ASCII").split("\\n");Path snap=tamper.resolve("state").resolve("txn-"+j[1]).resolve(name);DataManifest prior=DataManifest.read(snap,lim);DataManifest foreign=DataManifest.fromZip(src(third),lim,prior.resourceDirectory,"re3dxplus-data-v1");foreign.writeAtomic(snap,prior,lim);byte[] original=Files.readAllBytes(snap);try{tc.prepare(src(b),null);throw new Exception("changed transaction snapshot accepted");}catch(IOException expected){}ok(Arrays.equals(original,Files.readAllBytes(snap))&&val(tr).equals("old")&&!oldMatches(tr,a));}
  Path markerRace=Files.createTempDirectory("coord-marker-race-").toRealPath();DataCoordinator mc=coordinator(markerRace);Path mr=mc.prepare(src(a),null);try{mc.prepare(src(b),s->{if(s.equals("after-marker-invalidate"))throw new IOException("interrupted");});throw new Exception("fault missed");}catch(IOException expected){}Path mm=mr.resolve(".re3dxplus-install-v1");Files.write(mm,"user-marker".getBytes("UTF-8"));try{mc.prepare(src(b),null);throw new Exception("changed pending marker overwritten");}catch(IOException expected){}ok(new String(Files.readAllBytes(mm),"UTF-8").equals("user-marker")&&val(mr).equals("old"));
  Path t=Files.createTempDirectory("coord-adopt-").toRealPath(),base=Files.createDirectory(t.resolve("data"));Path legacy=Files.createDirectory(base.resolve(sha(a)+"-"+UUID.randomUUID()));Files.createDirectories(legacy.resolve("data"));Files.write(legacy.resolve("data/a"),"old".getBytes("UTF-8"));Files.write(legacy.resolve("data/obsolete"),"original".getBytes("UTF-8"));Files.write(legacy.resolve("data/user-obsolete"),"original".getBytes("UTF-8"));Files.write(legacy.resolve("extra"),new byte[]{1});Files.write(legacy.resolve(".re3dxplus-install-v1"),("re3dxplus-data-v1:"+sha(a)).getBytes("UTF-8"));DataCoordinator c=coordinator(t);ok(c.prepare(src(a),null).equals(legacy));ok(c.prepare(src(b),null).equals(legacy));ok(Files.exists(legacy.resolve("extra")));
  Files.write(legacy.resolve("data/a"),"user".getBytes("UTF-8"));try{c.prepare(src(a),null);throw new Exception("modified overwritten");}catch(IOException expected){}ok(val(legacy).equals("user"));
  Path restore=Files.createTempDirectory("coord-registry-loss-").toRealPath();DataCoordinator rc=coordinator(restore);Path rr=rc.prepare(src(a),null);Files.write(rr.resolve("personal"),"keep".getBytes("UTF-8"));rc.prepare(src(b),null);ok(rr.getFileName().toString().startsWith(sha(a)+"-"));Files.move(restore.resolve("state"),restore.resolve("state-backup"));ok(coordinator(restore).prepare(src(b),null).equals(rr));ok(new String(Files.readAllBytes(rr.resolve("personal")),"UTF-8").equals("keep"));try(DirectoryStream<Path> ds=Files.newDirectoryStream(restore.resolve("data"))){int count=0;for(Path ignored:ds)count++;ok(count==1);}
  for(boolean badMarker:new boolean[]{true,false}){Path z=Files.createTempDirectory("coord-bad-adoption-").toRealPath();DataCoordinator zc=coordinator(z);Path zr=zc.prepare(src(a),null);zc.prepare(src(b),null);Files.move(z.resolve("state"),z.resolve("state-backup"));Path target=badMarker?zr.resolve(".re3dxplus-install-v1"):zr.resolve("data/a");Files.write(target,"user-edited".getBytes("UTF-8"));try{coordinator(z).prepare(src(b),null);throw new Exception("invalid adoption accepted");}catch(IOException expected){}ok(new String(Files.readAllBytes(target),"UTF-8").equals("user-edited"));try(DirectoryStream<Path> ds=Files.newDirectoryStream(z.resolve("data"))){int count=0;for(Path ignored:ds)count++;ok(count==1);}}
  Path multi=Files.createTempDirectory("coord-multiple-").toRealPath();DataCoordinator ac=coordinator(multi);Path ar=ac.prepare(src(a),null);ac.prepare(src(b),null);Path second=Files.createDirectory(multi.resolve("data").resolve(sha(b)+"-"+UUID.randomUUID()));Files.write(second.resolve(".re3dxplus-install-v1"),("re3dxplus-data-v1:"+sha(b)).getBytes("UTF-8"));Files.move(multi.resolve("state"),multi.resolve("state-backup"));try{coordinator(multi).prepare(src(b),null);throw new Exception("ambiguous adoption accepted");}catch(IOException expected){}ok(Files.exists(ar)&&Files.exists(second));
